mat2 rotation_2d(float angle) {
    float cosinus = cos(angle), sinus = sin(angle);
    return mat2(cosinus, -sinus, sinus, cosinus);
}

float generer_bruit_3d(vec3 position) {
    position = fract(position * vec3(443.8975, 397.2973, 491.1871));
    position += dot(position, position.yxz + 19.19);
    return fract((position.x + position.y) * position.z);
}

float calculer_surface_gyroide(vec3 position) {
    return dot(sin(position), cos(position.yzx));
}

float bruit_fractal_fbm(vec3 position) {
    float accumulation = 0.0;
    float poids = 0.5;
    for (int octave = 0; octave < 5; octave++) {
        accumulation += poids * abs(calculer_surface_gyroide(position));
        position *= 2.02;
        position.xy *= rotation_2d(0.5);
        position.yz *= rotation_2d(0.3);
        poids *= 0.5;
    }
    return accumulation;
}

vec3 generer_fond_etoiles(vec3 direction_rayon) {
    vec3 couleur = vec3(0.002, 0.004, 0.01);

    vec3 p = direction_rayon * 250.0;
    vec3 cellule = floor(p);
    float n = generer_bruit_3d(cellule);

    if (n > 0.92) {
        vec3 centre = fract(p) - 0.5;
        float d = length(centre);

        float scintillement = sin(iTime * (3.0 + n * 10.0) + n * 62.8) * 0.5 + 0.5;
        float taille = (n - 0.92) * 20.0;

        float eclat = smoothstep(0.1 * taille, 0.0, d) * (0.3 + 0.7 * scintillement);

        vec3 couleur_etoile = mix(
            vec3(0.5, 0.7, 1.0),
            vec3(1.0, 0.8, 0.5),
            fract(n * 23.45)
        );

        couleur += couleur_etoile * eclat * 12.0;
    }

    vec3 p2 = direction_rayon * 500.0;
    vec3 cellule2 = floor(p2);
    float n2 = generer_bruit_3d(cellule2);
    if (n2 > 0.96) {
        vec3 centre2 = fract(p2) - 0.5;
        float eclat2 = smoothstep(0.08, 0.0, length(centre2));
        couleur += vec3(0.9, 0.95, 1.0) * eclat2 * 4.0;
    }

    return couleur;
}

vec2 estimer_distance_objet(vec3 pos_locale, float echelle) {
    vec3 position_fractale = pos_locale / echelle;
    for (int etape = 0; etape < 4; etape++) {
        position_fractale = abs(position_fractale) - vec3(0.4, 0.5, 0.3);
        position_fractale.xy *= rotation_2d(0.8);
        position_fractale.yz *= rotation_2d(0.6);
    }
    float distance_cavite_interne = (length(position_fractale.xz) - 0.08) * echelle;

    float micro_relief = sin(pos_locale.x * 25.0 / echelle) * sin(pos_locale.y * 25.0 / echelle) * sin(pos_locale.z * 25.0 / echelle) * 0.01 * echelle;
    float facteur_fbm_surface = smoothstep(0.2, 0.8, bruit_fractal_fbm((pos_locale / echelle) * 8.0));
    micro_relief += facteur_fbm_surface * 0.025 * echelle;

    float distance_sphere = length(pos_locale) - (1.25 * echelle);
    float distance_finale = max(distance_sphere, -distance_cavite_interne) + micro_relief;

    float identifiant_materiau = 1.0;
    if (facteur_fbm_surface > 0.45) {
        identifiant_materiau = 2.0;
    }

    return vec2(distance_finale * 0.7, identifiant_materiau);
}

vec2 estimer_distance_surface(vec3 position) {
    vec3 pos_planete = position;
    pos_planete.xz *= rotation_2d(iTime * 0.15);
    pos_planete.xy *= rotation_2d(iTime * 0.1);
    vec2 res_planete = estimer_distance_objet(pos_planete, 1.0);

    float temps_orbite = iTime * 0.6;
    float rayon_orbite = 2.2;
    vec3 pos_satellite = position - vec3(cos(temps_orbite) * rayon_orbite, sin(temps_orbite * 0.5) * 0.4, sin(temps_orbite) * rayon_orbite);
    pos_satellite.xz *= rotation_2d(iTime * 0.8);
    pos_satellite.yz *= rotation_2d(iTime * 0.5);
    vec2 res_satellite = estimer_distance_objet(pos_satellite, 0.22);

    if (res_satellite.x < res_planete.x) {
        return res_satellite;
    }
    return res_planete;
}

vec3 calculer_normale(vec3 position) {
    vec2 decalage = vec2(0.0015, 0.0);
    return normalize(vec3(
        estimer_distance_surface(position + decalage.xyy).x - estimer_distance_surface(position - decalage.xyy).x,
        estimer_distance_surface(position + decalage.yxy).x - estimer_distance_surface(position - decalage.yxy).x,
        estimer_distance_surface(position + decalage.yyx).x - estimer_distance_surface(position - decalage.yyx).x
    ));
}

float calculer_occlusion_ambiante(vec3 position, vec3 normale) {
    float accumulation_occlusion = 0.0;
    float facteur_echelle = 1.0;
    for (int echantillon = 0; echantillon < 5; echantillon++) {
        float distance_echantillon = 0.02 + 0.1 * float(echantillon) / 4.0;
        float distance_estimee = estimer_distance_surface(position + distance_echantillon * normale).x;
        accumulation_occlusion += (distance_echantillon - distance_estimee) * facteur_echelle;
        facteur_echelle *= 0.85;
    }
    return clamp(1.0 - 2.5 * accumulation_occlusion, 0.0, 1.0);
}

vec4 estimer_densite_volumique(vec3 position) {
    vec3 position_volumique = position * 1.8;
    position_volumique.xz *= rotation_2d(iTime * 0.2);
    position_volumique.y -= iTime * 0.3;

    float densite = bruit_fractal_fbm(position_volumique);

    vec3 position_noyau = position;
    position_noyau.xz *= rotation_2d(-iTime * 0.1);
    float distance_noyau = length(position_noyau) - 1.1;
    float limite_confinement = smoothstep(0.4, -0.6, distance_noyau);

    densite *= limite_confinement;

    vec3 couleur_sombre = vec3(0.02, 0.08, 0.35);
    vec3 couleur_intermediaire = vec3(0.85, 0.15, 0.02);
    vec3 couleur_lumineuse = vec3(0.98, 0.75, 0.12);

    vec3 couleur_volumique = mix(couleur_sombre, couleur_intermediaire, smoothstep(0.1, 0.45, densite));
    couleur_volumique = mix(couleur_volumique, couleur_lumineuse, smoothstep(0.45, 0.75, densite));

    return vec4(couleur_volumique, densite);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 coordonnees_ecran = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 position_souris = iMouse.xy / iResolution.xy;

    vec3 origine_rayon = vec3(0.0, 0.0, -3.8);
    vec3 direction_rayon = normalize(vec3(coordonnees_ecran, 1.35));

    if (iMouse.z > 0.0) {
        origine_rayon.yz *= rotation_2d((position_souris.y - 0.5) * 3.14159265);
        origine_rayon.xz *= rotation_2d((position_souris.x - 0.5) * 6.2831853);
        vec3 cible = vec3(0.0);
        vec3 axe_z = normalize(cible - origine_rayon);
        vec3 axe_x = normalize(cross(axe_z, vec3(0.0, 1.0, 0.0)));
        vec3 axe_y = normalize(cross(axe_x, axe_z));
        direction_rayon = normalize(coordonnees_ecran.x * axe_x + coordonnees_ecran.y * axe_y + 1.35 * axe_z);
    }

    float bruit_temporel = generer_bruit_3d(vec3(fragCoord, float(iFrame))) * 0.02;

    float distance_marche = bruit_temporel;
    float distance_impact = -1.0;
    float identifiant_materiau_impact = 0.0;

    for (int etape = 0; etape < 128; etape++) {
        vec3 position_courante = origine_rayon + direction_rayon * distance_marche;
        vec2 resultat_surface = estimer_distance_surface(position_courante);
        if (resultat_surface.x < 0.0008) {
            distance_impact = distance_marche;
            identifiant_materiau_impact = resultat_surface.y;
            break;
        }
        distance_marche += resultat_surface.x;
        if (distance_marche > 7.0) {
            break;
        }
    }

    vec3 position_lumiere_1 = vec3(2.5 * sin(iTime * 0.8), 2.0, 2.5 * cos(iTime * 0.8));
    vec3 couleur_lumiere_1 = vec3(1.0, 0.85, 0.6) * 3.0;

    vec3 position_lumiere_2 = vec3(-2.5 * cos(iTime * 0.5), -1.5, -2.0);
    vec3 couleur_lumiere_2 = vec3(0.1, 0.4, 0.9) * 2.0;

    vec3 couleur_fond = generer_fond_etoiles(direction_rayon);
    vec3 couleur_finale = couleur_fond;

    if (distance_impact > 0.0) {
        vec3 position_impact = origine_rayon + direction_rayon * distance_impact;
        vec3 normale_surface = calculer_normale(position_impact);
        vec3 direction_vue = -direction_rayon;
        float occlusion_ambiante = calculer_occlusion_ambiante(position_impact, normale_surface);

        vec3 couleur_albedo = vec3(0.04, 0.04, 0.05);
        float rugosite = 0.35;
        float metallicite = 0.1;

        if (identifiant_materiau_impact > 1.5) {
            couleur_albedo = vec3(0.65, 0.5, 0.25);
            rugosite = 0.15;
            metallicite = 0.85;
        }

        vec3 couleur_surface = vec3(0.0);

        vec3 directions_lumieres[2];
        directions_lumieres[0] = position_lumiere_1 - position_impact;
        directions_lumieres[1] = position_lumiere_2 - position_impact;

        vec3 couleurs_lumieres[2];
        couleurs_lumieres[0] = couleur_lumiere_1;
        couleurs_lumieres[1] = couleur_lumiere_2;

        for (int indice_lumiere = 0; indice_lumiere < 2; indice_lumiere++) {
            float distance_lumiere = length(directions_lumieres[indice_lumiere]);
            vec3 direction_lumiere_normalisee = directions_lumieres[indice_lumiere] / distance_lumiere;
            vec3 demi_vecteur = normalize(direction_vue + direction_lumiere_normalisee);

            float attenuation = 1.0 / (1.0 + distance_lumiere * distance_lumiere * 0.2);
            float produit_normale_lumiere = max(dot(normale_surface, direction_lumiere_normalisee), 0.0);
            float produit_normale_demi = max(dot(normale_surface, demi_vecteur), 0.0);

            float puissance_speculaire = exp2(10.0 * (1.0 - rugosite) + 1.0);
            float intensite_speculaire = pow(produit_normale_demi, puissance_speculaire) * ((puissance_speculaire + 2.0) / 8.0);

            vec3 reflectaion_fresnel_zero = mix(vec3(0.04), couleur_albedo, metallicite);
            vec3 facteur_fresnel = reflectaion_fresnel_zero + (1.0 - reflectaion_fresnel_zero) * pow(clamp(1.0 - dot(demi_vecteur, direction_vue), 0.0, 1.0), 5.0);

            vec3 composante_diffuse = couleur_albedo * (1.0 - metallicite) * (1.0 - facteur_fresnel) / 3.14159265;
            vec3 composante_speculaire = facteur_fresnel * intensite_speculaire;

            couleur_surface += (composante_diffuse + composante_speculaire) * couleurs_lumieres[indice_lumiere] * produit_normale_lumiere * attenuation;
        }

        float effet_fresnel_bord = pow(clamp(1.0 - max(dot(normale_surface, direction_vue), 0.0), 0.0, 1.0), 4.0);
        couleur_surface += vec3(0.2, 0.3, 0.5) * effet_fresnel_bord * occlusion_ambiante * 0.5;
        couleur_surface *= occlusion_ambiante;

        couleur_finale = couleur_surface;
    }

    float debut_volume = 0.5 + bruit_temporel * 0.5;
    float fin_volume = (distance_impact > 0.0) ? distance_impact : 4.0;
    float pas_volumique = (fin_volume - debut_volume) / 64.0;
    float distance_volume_courante = debut_volume;

    vec4 accumulation_volumique = vec4(0.0);

    for (int echantillon_volume = 0; echantillon_volume < 64; echantillon_volume++) {
        if (distance_volume_courante >= fin_volume || accumulation_volumique.a >= 0.98) {
            break;
        }

        vec3 position_volumique_courante = origine_rayon + direction_rayon * distance_volume_courante;
        vec4 resultat_volume = estimer_densite_volumique(position_volumique_courante);
        float densite_locale = resultat_volume.a;

        if (densite_locale > 0.01) {
            vec3 direction_ombre_1 = normalize(position_lumiere_1 - position_volumique_courante);
            float densite_ombre_1 = estimer_densite_volumique(position_volumique_courante + direction_ombre_1 * 0.12).a;
            vec3 diffusion_lumiere_1 = couleur_lumiere_1 * exp(-densite_ombre_1 * 5.0) * 0.6;

            vec3 direction_ombre_2 = normalize(position_lumiere_2 - position_volumique_courante);
            float densite_ombre_2 = estimer_densite_volumique(position_volumique_courante + direction_ombre_2 * 0.12).a;
            vec3 diffusion_lumiere = diffusion_lumiere_1 + couleur_lumiere_2 * exp(-densite_ombre_2 * 4.0) * 0.4;

            vec3 emission_volumique = resultat_volume.rgb * (diffusion_lumiere + vec3(0.1, 0.15, 0.25));

            float opacite_pas = (1.0 - accumulation_volumique.a) * clamp(densite_locale * pas_volumique * 16.0, 0.0, 1.0);
            accumulation_volumique.rgb += emission_volumique * opacite_pas;
            accumulation_volumique.a += opacite_pas;
        }

        distance_volume_courante += pas_volumique;
    }

    couleur_finale = mix(couleur_fond, couleur_finale, (distance_impact > 0.0) ? 1.0 : 0.0);
    couleur_finale = accumulation_volumique.rgb + couleur_finale * (1.0 - accumulation_volumique.a);

    couleur_finale = vec3(1.0) - exp(-couleur_finale * 1.8);
    couleur_finale = pow(couleur_finale, vec3(0.454545));

    vec2 coordonnees_normalisees = fragCoord / iResolution.xy;
    couleur_finale *= pow(16.0 * coordonnees_normalisees.x * coordonnees_normalisees.y * (1.0 - coordonnees_normalisees.x) * (1.0 - coordonnees_normalisees.y), 0.15);

    fragColor = vec4(couleur_finale, 1.0);
}
